 "content": "def transform(grid):
    # Return the compressed raster of non-background divider crossings.
    from collections import Counter
    h,w=len(grid),len(grid[0])
    background=Counter(x for row in grid for x in row).most_common(1)[0][0]
    def divider_coords(axis):
        n,m=(h,w) if axis==0 else (w,h)
        coords=[]
        for i in range(n):
            line=[grid[i][j] if axis==0 else grid[j][i] for j in range(m)]
            if line.count(background)>=.7*m: coords.append(i)
        gaps=Counter(b-a for a,b in zip(coords,coords[1:]))
        if gaps:
            pitch=gaps.most_common(1)[0][0]
            coords=max(([i for i in coords if i%pitch==phase] for phase in range(pitch)),key=len)
        return coords
    rs,cs=divider_coords(0),divider_coords(1)
    if not rs or not cs:return [[background]]
    # Remove entirely empty outer crossings; preserve internal pattern rows/cols.
    out=[[grid[r][c] for c in cs] for r in rs]
    while len(out)>1 and all(v==background for v in out[0]):out.pop(0)
    while len(out)>1 and all(v==background for v in out[-1]):out.pop()
    while out and len(out[0])>1 and all(row[0]==background for row in out):
        for row in out:row.pop(0)
    while out and len(out[0])>1 and all(row[-1]==background for row in out):
        for row in out:row.pop()
    return out
